EditorApplication.delayCall+=()=>{try{
var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene(Racer.Editor.BackyardForwardAuthoring.ScenePath);var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();race.road.Initialize();var course=race.GetComponent<Racer.BackyardForwardCourse>();var prior=GameObject.Find("Forward teal navigation - no colliders");if(prior)UnityEngine.Object.DestroyImmediate(prior);foreach(var t in race.gates[0].GetComponentsInChildren<Transform>().Where(t=>t.name=="Non-colliding gate marking"&&t.localScale.y<.1f).ToArray())UnityEngine.Object.DestroyImmediate(t.gameObject);var root=new GameObject("Forward teal navigation - no colliders").transform;
var mat=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.FindAssets("CR117 main teal t:Material").Select(AssetDatabase.GUIDToAssetPath).First());
float Ground(Vector3 p)=>Physics.RaycastAll(new Vector3(p.x,250,p.z),Vector3.down,500,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")||h.collider.name=="Decorative Road pavement").OrderBy(h=>h.distance).First().point.y;
int count=0;for(float s=18;s<race.road.Length;s+=38){var p=race.road.At(s,out var f);if(p.x>=390&&p.x<=410&&p.z<35)continue;if(Enumerable.Range(0,course.launchStations.Length).Any(i=>s>course.launchStations[i]-5&&s<course.landingStations[i]+10))continue;if(Math.Abs(Ground(p)-p.y)>1)continue;
var go=new GameObject("Main teal trail arrow",typeof(MeshFilter),typeof(MeshRenderer));go.transform.SetParent(root);go.transform.SetPositionAndRotation(p,Quaternion.LookRotation(Vector3.ProjectOnPlane(f,Vector3.up)));float w=.65f;var v=new[]{new Vector3(-w*.4f,0,-1.7f),new(w*.4f,0,-1.7f),new(w*.4f,0,0),new(w,0,0),new(0,0,1.7f),new(-w,0,0),new(-w*.4f,0,0)};for(int j=0;j<v.Length;j++){var q=go.transform.TransformPoint(v[j]);q.y=Ground(q)+.028f;v[j]=go.transform.InverseTransformPoint(q);}var mesh=new Mesh{vertices=v,triangles=new[]{0,6,1,1,6,2,6,5,4,6,4,2,2,4,3}};mesh.RecalculateNormals();mesh.RecalculateBounds();var assetPath=Racer.Editor.BackyardForwardAuthoring.Folder+"/Arrow-"+(count++)+".asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(assetPath);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,assetPath);go.GetComponent<MeshFilter>().sharedMesh=mesh;go.GetComponent<Renderer>().sharedMaterial=mat;}
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();System.IO.File.WriteAllText("Docs/BackyardForward/guidance.txt",count+" accepted teal ground arrows, conformed to final terrain; no collision, no arrows in flight/landing zones or parking");
}catch(Exception e){System.IO.File.WriteAllText("Docs/BackyardForward/guidance-error.txt",e.ToString());}};return "Scheduled grounded teal Forward guidance";
